// Read-only field-population audit. For every page singleton it compares the
// SCHEMA fields (from studio/schema.json, regenerated by `npm run typegen`)
// against the actual PUBLISHED document, and lists which editable fields are
// empty. An empty field means the Studio shows a blank input while the live
// site renders the code's inline hardcoded fallback, which is exactly the
// "why are these fields empty?" confusion.
//
// This does NOT tell you whether a field is wired into the template (a field
// can be populated but ignored by the page, or hardcoded with no field at all).
// That is the code-side audit. This is the data-side companion.
//
// Run: node scripts/audit-field-population.mjs

import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readFileSync } from 'node:fs';
import { createClient } from '@sanity/client';

import { loadEnv } from './lib/loadEnv.mjs';
const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');

const env = loadEnv(root);
const projectId = env.PUBLIC_SANITY_PROJECT_ID;
const dataset = env.PUBLIC_SANITY_DATASET ?? 'production';
const apiVersion = env.PUBLIC_SANITY_API_VERSION ?? '2026-05-01';
const token = env.SANITY_API_WRITE_TOKEN || env.SANITY_API_READ_TOKEN;

if (!projectId) {
  console.error('Missing PUBLIC_SANITY_PROJECT_ID in .env');
  process.exit(1);
}

const client = createClient({ projectId, dataset, apiVersion, token, useCdn: false });

const schema = JSON.parse(readFileSync(resolve(root, 'studio', 'schema.json'), 'utf-8'));
const SYS = new Set(['_id', '_type', '_rev', '_createdAt', '_updatedAt']);

// type name -> [editable field names]
function schemaFields(typeName) {
  const t = schema.find((x) => x.name === typeName);
  if (!t || !t.attributes) return [];
  return Object.keys(t.attributes).filter((k) => !SYS.has(k));
}

function isEmpty(v) {
  if (v == null) return true;
  if (typeof v === 'string') return v.trim().length === 0;
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.keys(v).filter((k) => !SYS.has(k)).length === 0;
  return false;
}

const SINGLETONS = [
  'siteSettings',
  'homePage',
  'aboutPage',
  'worshipPage',
  'beliefsPage',
  'musicPage',
  'staffPage',
  'growPage',
  'servePage',
  'kidsPage',
  'foodPage',
  'eventsPage',
  'sermonsPage',
  'useOurSpacePage',
  'weddingsPage',
  'givePage',
  'faqPage',
  'contactPage',
  'notFoundPage',
  'privacyPage',
];

async function run() {
  console.log(`\nField-population audit — ${projectId}/${dataset}`);
  console.log('Per singleton: EMPTY editable fields (Studio blank -> site shows code fallback).\n');

  for (const t of SINGLETONS) {
    const fields = schemaFields(t);
    if (fields.length === 0) {
      console.log(`${t}: (no schema fields found)`);
      continue;
    }
    const doc = await client.fetch(`*[_type == $t && !(_id in path("drafts.**"))][0]`, { t });
    if (!doc) {
      console.log(
        `\n${t}: NO PUBLISHED DOC — all ${fields.length} fields empty (page is 100% code fallback)`,
      );
      continue;
    }
    const empty = fields.filter((f) => isEmpty(doc[f]));
    const set = fields.filter((f) => !isEmpty(doc[f]));
    console.log(`\n${t}: ${set.length}/${fields.length} set`);
    if (empty.length) console.log(`  EMPTY (${empty.length}): ${empty.join(', ')}`);
  }
  console.log('');
}

run().catch((e) => {
  console.error('Audit failed:', e.message);
  process.exit(1);
});
